// Arma el pedido a Microsoft 365: responder dentro de la conversación o enviar un correo nuevo.
const p = $json.body || {};
const html = t => String(t || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])).replace(/\r?\n/g, '<br>');
const adjuntos = (p.adjuntos || []).map(a => ({
  '@odata.type': '#microsoft.graph.fileAttachment',
  name: a.nombre,
  contentBytes: a.datos
}));
const base = 'https://graph.microsoft.com/v1.0/users/' + p.buzon;

if (p.accion === 'responder') {
  // La respuesta va al remitente, con el correo original citado debajo, y queda en Elementos enviados.
  return [{ json: {
    url: base + '/messages/' + encodeURIComponent(p.message_id) + '/reply',
    cuerpo: { comment: html(p.texto), message: { attachments: adjuntos } }
  } }];
}

return [{ json: {
  url: base + '/sendMail',
  cuerpo: {
    message: {
      subject: p.asunto || '',
      body: { contentType: 'HTML', content: html(p.texto) },
      toRecipients: [{ emailAddress: { address: p.para } }],
      attachments: adjuntos
    },
    saveToSentItems: true
  }
} }];

// Microsoft responde vacío cuando el envío salió bien.
const r = $input.first().json || {};
if (r.error) {
  const detalle = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return [{ json: { ok: false, error: 'Microsoft 365 no envió el correo: ' + detalle } }];
}
return [{ json: { ok: true } }];
